h planks for every new building in the village."]]},{"stat":"made_ironbar","targets":[10,20,30],"titles":[["Hot iron","Smelt iron bars at the Smithy."],["Strike while it’s hot","Ore and logs into iron bars at the forge."]]},{"stat":"made_pickaxe","targets":[20,40,60],"titles":[["Pick it up","Forge pickaxes for the miners."],["New tools","Sharp pickaxes for the deep tunnels."]]},{"stat":"made_rooftile","targets":[20,40,60],"titles":[["Roof over our heads","Fire roof tiles at the Potter’s Kiln."],["Red rooftops","Tile after tile for the village roofs."]]},{"stat":"made_linen","targets":[18,35,55],"titles":[["White as linen","Weave flax into linen at the Linen Loft."],["Loom day","The looms clatter from morning till night."]]},{"stat":"made_builderscrate","targets":[2,3,7],"titles":[["Crated and ready","Builder’s crates from the Lumber Camp for the farm’s upgrades."],["Packed for building","Planks, tiles and iron, all in one sturdy crate."]]},{"stat":"made_lavendersoap","targets":[18,35,55],"titles":[["Wash day","Lavender soap from the Soap Maker."],["Soap bubbles","Bar after bar of sweet lavender soap."]]},{"stat":"made_scentedsachet","targets":[18,35,55],"titles":[["Sweet sachets","Lavender and linen sewn into scented sachets."],["Fresh as lavender","A sachet for every drawer in the village."]]},{"stat":"made_silvercandlestick","targets":[2,3,6],"titles":[["Silver shine","Silver bars and candles into fine candlesticks."],["Polished silver","Candlesticks fit for the town’s finest tables."]]},{"stat":"made_rubyring","targets":[2,3,5],"titles":[["Ruby red","Set rubies in silver at the Jeweller."],["A ring of red","Rubies from deep in the Mine, set in silver."]]}],[{"stat":"village_requests","targets":[2,3,5],"titles":[["Helping the village","Bring the villagers the goods they ask for."],["A busy square","Villagers are waiting at the market square with their requests."]]}],[{"stat":"lake_fish","targets":[5,10,15],"titles":[["Gone fishing","Row out on the village lake and cast your line."],["Lake day","Catch fish from the rowboat on the village lake."]]},{"stat":"upgrades","targets":[2,3,5],"titles":[["Builders’ day","Make your buildings better and faster."],["Hammer time","Upgrade the buildings that work hardest for you."]]}]]]';
 r bigint[]:=array[]::bigint[]; i int; lg int; head int; rest int[]; g1 int; g2 int; sizes int[]; groups int[]; kind jsonb; picked jsonb; title jsonb; main jsonb; pool jsonb;
 leagues jsonb:='[]'::jsonb;
begin
 for i in 1..8 loop r:=r||abs(hashtextextended('harvest-event-mix:'||n||':'||i,0)); end loop;
 head:=(n%5)::int;
 rest:=array_remove(array[0,1,2,3,4],head);
 g1:=rest[1+(r[1]%4)::int];rest:=array_remove(rest,g1);
 g2:=rest[1+(r[2]%3)::int];
 groups:=array[head,g1,g2];
 sizes:=case when r[3]%2=0 then array[2,1,0] else array[1,1,1] end;   -- index into targets: 0 easy, 1 medium, 2 hard
 for lg in 0..jsonb_array_length(pools)-1 loop
  pool:=pools->lg;picked:='[]'::jsonb;
  for i in 1..3 loop
   kind:=(pool->groups[i])->((r[3+i]%jsonb_array_length(pool->groups[i]))::int);
   if i=1 then main:=kind; end if;
   picked:=picked||jsonb_build_array(jsonb_build_object('stat',kind->>'stat','target',(kind->'targets'->>sizes[i])::int));
  end loop;
  title:=main->'titles'->((r[7]%jsonb_array_length(main->'titles'))::int);
  leagues:=leagues||jsonb_build_array(jsonb_build_object('title',title->>0,'description',title->>1,'objectives',picked));
 end loop;
 -- The event's own title and goals are the Sprout League's: admin screens and any older reader keep working.
 return jsonb_build_object('title',leagues->0->>'title','description',leagues->0->>'description','objectives',leagues->0->'objectives','leagues',leagues);
end $function$;

create or replace function public.harvest_event_validate()
 returns trigger language plpgsql set search_path to '' as $function$
declare objective jsonb; k text;
begin
 perform pg_advisory_xact_lock(724919);
 if TG_OP='UPDATE' and old.starts_at<=now() and (new.title<>old.title or new.description<>old.description or new.starts_at<>old.starts_at or new.ends_at<>old.ends_at or new.objectives<>old.objectives or new.rewards<>old.rewards) then raise exception 'Started events are frozen. Create a new event to change the rules.'; end if;
 if new.active and new.ends_at>now() and exists(select 1 from public.live_events e where e.id<>new.id and e.active and e.starts_at<new.ends_at and e.ends_at>new.starts_at) then raise exception 'Active events cannot overlap.'; end if;
 if jsonb_typeof(new.objectives)<>'array' or jsonb_array_length(new.objectives) not between 1 and 4 then raise exception 'Choose 1–4 objectives.'; end if;
 for objective in select value from jsonb_array_elements(new.objectives) loop
  if coalesce(objective->>'stat','') not in ('harvested','produced','watered','tended','chores','deliveries','harvest_wheat','harvest_corn','harvest_lettuce','harvest_barley','harvest_greenbeans','harvest_cabbage','made_eggs','planted','sold','earned','coins_spent','diamonds_spent','activities','upgrades','made_feed','made_milk','made_cheese','made_flour','fertilized','harvest_cauliflower','made_grainmeal','made_bread','parallel_batches','boosts_used','activity_rounds','sold_wheat','made_salad','made_fertilizer','sold_eggs','made_vegetables','made_pickles','made_oil','made_beangratin','made_applepie','made_orchardsalad','made_pie','made_stew','sold_cheese','tractor','glasshouse_batches','made_berrysmoothie','made_applecompote','made_pickledbeans','made_truffleomelette','made_berrycheesecake','made_applejuice','made_orchardjuice','made_berrypreserves','made_truffles','made_honey','made_wool','made_squashsoup','made_yarn','made_cloth','made_goatmilk','made_goatcheese','made_candles','made_cider','made_cherryjam','valley_baskets','made_stone','made_ironore','made_timber','made_packedlunch','village_batches','made_plank','village_requests','lake_fish','made_clay','made_potatoes','made_ironbar','made_pickaxe','made_rooftile','made_flax','made_lavender','made_linen','made_builderscrate','made_lavendersoap','made_scentedsachet','made_silvercandlestick','made_rubyring') or coalesce((objective->>'target')::integer,0) not between 1 and 10000 then raise exception 'Invalid event objective.'; end if;
 end loop;
 if (select count(distinct value->>'stat') from jsonb_array_elements(new.objectives))<>jsonb_array_length(new.objectives) then raise exception 'Objectives must be unique.'; end if;
 foreach k in array array['coins','diamondMin','diamondMax','participantStep','poolCap'] loop
  if not new.rewards ? k or jsonb_typeof(new.rewards->k)<>'number' or (new.rewards->>k)::numeric<>trunc((new.rewards->>k)::numeric) then raise exception 'Reward settings must be whole numbers.'; end if;
 end loop;
 if (new.rewards->>'coins')::integer not between 0 and 300 or (new.rewards->>'diamondMin')::integer not between 0 and 1 or (new.rewards->>'diamondMax')::integer not between 1 and 3 or (new.rewards->>'participantStep')::integer not between 10 and 1000 or (new.rewards->>'poolCap')::integer not between 0 and 200 then raise exception 'Reward settings exceed safe limits.'; end if;
 return new;
end $function$;

-- 6. Self-check of the pick: 500 slots from now, every one with 12 leagues of 3 goals and a title.
do $check$ declare n bigint; t jsonb; s bigint:=floor(extract(epoch from now())/21600)::bigint; begin
 for n in s..s+500 loop t:=public.harvest_event_pick(n);
  if jsonb_array_length(t->'leagues')<>12 or exists(select 1 from jsonb_array_elements(t->'leagues') l where jsonb_array_length(l->'objectives')<>3 or coalesce(l->>'title','')='') then raise exception 'pick %',n; end if;
 end loop; end $check$;

-- 7. The automatic events made ahead get the village leagues. The pick is the same for the farm leagues, so only 6..11 are
-- added; a row whose first 6 leagues would change is left alone (and the after-check then refuses).
update public.live_events e set leagues=x.l
 from (select id, public.harvest_event_pick(floor(extract(epoch from starts_at)/21600)::bigint)->'leagues' l from public.live_events
       where created_by is null and settled_at is null and starts_at>now() and jsonb_array_length(leagues)=6) x
 where e.id=x.id and (select jsonb_agg(v order by i) from jsonb_array_elements(x.l) with ordinality t(v,i) where i<=6)=e.leagues;

-- 8. After-check, in the same transaction.
do $after$ declare fn text; want jsonb:='{"harvest_event_league(integer)":"ea594ad4aeb110d5858de5cdaf68ddbe","harvest_event_league_for(integer,jsonb,smallint)":"72ba9cc06862bab8a5778cecd96fbaa7","harvest_event_settle(uuid)":"b73dea6778379f0bc6503f7bccad1870","harvest_event_progress()":"4681019789851e424d9a12f74f843077","harvest_event_board(uuid)":"c509587a78de0cdc576cd6681ba9a29f","harvest_event_pick(bigint)":"56d9b813f0b9223c59251ff07d0bbc28","harvest_event_validate()":"588cad3b5889d187cfcff6f0f05182fe"}'; begin
 for fn in select jsonb_object_keys(want) loop
  -- is distinct from: a missing function (NULL) fails too.
  if (select md5(prosrc) from pg_proc where oid=to_regprocedure('public.'||fn)) is distinct from want->>fn then raise exception 'public.% did not come out as generated',fn; end if;
 end loop;
 -- The headers as live: security definer, volatility and search_path, then the grants.
 if exists(select 1 from (values ('harvest_event_board(uuid)',true,'s'),('harvest_event_settle(uuid)',false,'v'),('harvest_event_progress()',false,'v'),
    ('harvest_event_validate()',false,'v'),('harvest_event_pick(bigint)',false,'s'),('harvest_event_league(integer)',false,'i'),
    ('harvest_event_league_for(integer,jsonb,smallint)',false,'i')) w(fn,secdef,vol)
   left join pg_proc p on p.oid=to_regprocedure('public.'||w.fn)
   where p.oid is null or p.prosecdef is distinct from w.secdef or p.provolatile::text is distinct from w.vol or p.proconfig is distinct from array['search_path=""'])
  then raise exception 'a function header changed (security definer, volatility or search_path)'; end if;
 if exists(select 1 from unnest(array['harvest_event_board(uuid)','harvest_event_settle(uuid)','harvest_event_progress()','harvest_event_validate()','harvest_event_pick(bigint)']) fn
    where (select proacl::text from pg_proc where oid=to_regprocedure('public.'||fn)) is distinct from '{postgres=X/postgres,service_role=X/postgres}')
  or (select proacl::text from pg_proc where oid='public.harvest_event_league(integer)'::regprocedure) is distinct from '{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}'
  or not has_function_privilege('service_role','public.harvest_event_league_for(integer,jsonb,smallint)','execute')
  then raise exception 'the grants of a harvest_event function changed'; end if;
 if array(select public.harvest_event_league(l) from unnest(array[14,15,29,30,89,90,99,100,120,121,140,141,160,161,180,181,200,201,999]) l)
   <>array[0,0,0,1,4,5,5,6,6,7,7,8,8,9,9,10,10,11,11]::smallint[] then raise exception 'harvest_event_league'; end if;
 if public.harvest_event_league_for(150,'[{},{},{},{},{},{}]')<>5 or public.harvest_event_league_for(150,null)<>5
   or public.harvest_event_league_for(150,(select jsonb_agg(x) from generate_series(1,12) x))<>8
   or public.harvest_event_league_for(150,(select jsonb_agg(x) from generate_series(1,12) x),1::smallint)<>5
   or public.harvest_event_league_for(150,(select jsonb_agg(x) from generate_series(1,12) x),2::smallint)<>8
   or public.harvest_event_league_for(95,(select jsonb_agg(x) from generate_series(1,12) x),1::smallint)<>5 then raise exception 'harvest_event_league_for'; end if;
 if exists(select 1 from public.live_events where created_by is null and settled_at is null and starts_at>now() and jsonb_array_length(leagues)<>12)
  then raise exception 'an automatic event that has not started still has 6 leagues'; end if;
 if not exists(select 1 from public.live_events where created_by is null and starts_at>now()) then raise notice 'no future event yet; the next cron run makes it with 12 leagues'; end if;
 -- Last: still in the break by the clock. now() is the time the transaction began, so a Part B started at :5x that runs past :00
 -- would have changed the leagues and rules of an event that already started. Roll everything back instead.
 if exists(select 1 from public.live_events where active and starts_at<=clock_timestamp() and ends_at>clock_timestamp()) then
  raise exception 'Part B ran into the next event; run it again in the next break.'; end if;
end $after$;
commit;
